<p><a href="/teacher">← My sections</a></p><h2 class="h5"><?= e($a['title']) ?></h2><p class="text-muted"><?= nl2br(e($a['instructions'])) ?></p><div class="row g-3"><?php foreach($items as $sb): ?><div class="col-md-6"><div class="card"><div class="card-body"><h3 class="h6"><?= e($sb['student_name']) ?></h3><p><a href="/teacher/submissions/<?= (int)$sb['id'] ?>/download">Download submission</a> · <?= e($sb['submitted_at']) ?></p><form method="post" action="/teacher/grades"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><input type="hidden" name="submission_id" value="<?= (int)$sb['id'] ?>"><label class="form-label">Score (0–100)</label><input required type="number" min="0" max="100" step="0.01" name="score" value="<?= e($sb['score']!==null?(string)$sb['score']:'') ?>" class="form-control mb-2"><label class="form-label">Feedback</label><textarea name="feedback" class="form-control mb-2"><?= e($sb['feedback']) ?></textarea><label class="form-label">Visibility</label><select name="status" class="form-select mb-3"><option value="draft" <?= $sb['status']==='draft'?'selected':'' ?>>Draft (hidden)</option><option value="released" <?= $sb['status']==='released'?'selected':'' ?>>Released (visible to student)</option></select><button class="btn btn-primary">Save grade</button></form></div></div></div><?php endforeach ?></div><?php if(!$items): ?><p>No submissions yet.</p><?php endif ?>
